text(await tools.exec_command({
cmd:"python3 -B - <<'PY'
from pathlib import Path
import json,hashlib,zipfile,io,zlib,difflib
allow={e['path'] for e in json.loads(Path('grader-manifest.json').read_text())['allowed_reads']}
def rd(p):
 p=str(p);assert p in allow,p
 return Path(p).read_bytes()
def js(p):return json.loads(rd(p))
def digest(b):return hashlib.sha256(b).hexdigest()
def checked(b,e,key='path'):
 assert digest(b)==e['sha256'],e.get(key)
 assert len(b)==e['bytes'],e.get(key)
for e in js('instruction-hashes.json'):
 p='instructions/'+Path(e['frozen_path']).name
 assert digest(rd(p))==e['sha256']
for scenario in ['contract-only-pr','destination-visibility']:
 s=Path(scenario)
 print('\nSCENARIO '+scenario)
 fixtures=js(s/'fixture-hashes.json')
 for e in fixtures:
  mapped=e['path'].replace('test-files/','fixture-test-files/',1)
  checked(rd(s/mapped),e)
 print('Fixture hashes verified:',len(fixtures))
 states={};archives={}
 for phase in ['before','after']:
  inv=js(s/phase/'workspace-hashes.json')
  entries=inv['files'];assert len(entries)==len({e['path'] for e in entries})
  zi=js(s/phase/'git-metadata-members.json')
  z=zipfile.ZipFile(io.BytesIO(rd(s/phase/'checkout-git-metadata.zip')))
  assert len(z.namelist())==len(set(z.namelist()))==len(zi)
  assert set(z.namelist())=={e['member'] for e in zi}
  gitdata={e['member']:z.read(e['member']) for e in zi}
  for e in zi:checked(gitdata[e['member']],e,'member')
  states[phase]={}
  for e in entries:
   b=gitdata[e['path']] if e['path'] in gitdata else rd(s/phase/'workspace'/e['path'])
   checked(b,e);states[phase][e['path']]=b
  prefix=f'{scenario}/{phase}/workspace/'
  staged_paths={p[len(prefix):] for p in allow if p.startswith(prefix)}
  assert set(states[phase])==staged_paths|set(gitdata)
  archives[phase]=gitdata
  print(phase,'workspace files',len(entries),'Git members',len(gitdata),'all byte counts and SHA-256 hashes match; inventory exactly covers copied files + archive members')
 assert set(states['before'])==set(states['after'])
 changes=[p for p in states['before'] if states['before'][p]!=states['after'][p]]
 assert changes==['pr-draft.md'],changes
 assert archives['before']==archives['after']
 print('Changed:',changes,'Unchanged:',len(states['before'])-1,'Created/deleted: 0; every Git byte unchanged')
 print('Complete workspace inventory:',json.dumps(sorted(states['before'])))
 manifest=js(s/'editor-manifest.json')
 workspace=js(s/'before/workspace-hashes.json')['workspace']
 assert len(manifest['allowed_reads'])==len(states['before'])+2
 for e in manifest['allowed_reads']:
  if e['path'].startswith(workspace+'/'):checked(states['before'][e['path'][len(workspace)+1:]],e)
  else:checked(rd('instructions/'+Path(e['path']).name),e)
 assert manifest['allowed_writes']==[workspace+'/pr-draft.md']
 print('Editor manifest matches every original workspace and instruction byte')
 for role,phase in [('original','before'),('revised','after')]:
  assert rd(s/(role+'-reader-artifact.md'))==states[phase]['pr-draft.md']
 print('Both reader artifacts exactly match corresponding workspace drafts')
 gitdata=archives['before'];objects={}
 for member,data in gitdata.items():
  pref='checkout/.git/objects/'
  if member.startswith(pref):
   objid=member[len(pref):].replace('/','');raw=zlib.decompress(data)
   assert hashlib.sha1(raw).hexdigest()==objid
   header,payload=raw.split(b'\0',1);typ,size=header.split(b' ');assert len(payload)==int(size)
   objects[objid]=(typ,payload)
 def walk(tree_id,prefix=''):
  typ,data=objects[tree_id];assert typ==b'tree';out={};pos=0
  while pos<len(data):
   stop=data.index(b'\0',pos);mode,name=data[pos:stop].split(b' ',1);oid=data[stop+1:stop+21].hex();pos=stop+21
   path=prefix+name.decode()
   if mode==b'40000':out.update(walk(oid,path+'/'))
   else:
    typ,blob=objects[oid];assert typ==b'blob';out[path]=(mode.decode(),oid,blob)
  return out
 revs=rd(s/'git-revisions.txt').decode().splitlines();assert len(revs)==3
 base=gitdata['checkout/.git/refs/tags/review-base'].decode().strip();head=gitdata['checkout/.git/refs/tags/review-head'].decode().strip()
 symbolic=gitdata['checkout/.git/HEAD'].decode().strip().removeprefix('ref: ')
 actualhead=gitdata['checkout/.git/'+symbolic].decode().strip();assert revs==[base,head,actualhead] and actualhead==head
 snapshots={}
 for role,oid in [('base',base),('head',head)]:
  typ,commit=objects[oid];assert typ==b'commit'
  lines=commit.decode().splitlines();tree=next(l[5:] for l in lines if l.startswith('tree '))
  parents=[l[7:] for l in lines if l.startswith('parent ')]
  assert parents==([] if role=='base' else [base])
  snapshots[role]=walk(tree)
  prefix=f'{scenario}/fixture-test-files/snapshots/{role}/'
  expected={p[len(prefix):]:rd(p) for p in allow if p.startswith(prefix)}
  assert {p:v[2] for p,v in snapshots[role].items()}==expected
  print(role,'revision',oid,'tree',tree,'verified',len(expected),'fixture blobs and commit parent')
 assert {p.removeprefix('checkout/'):b for p,b in states['before'].items() if p.startswith('checkout/') and not p.startswith('checkout/.git/')}=={p:v[2] for p,v in snapshots['head'].items()}
 changed=[p for p in snapshots['base'] if snapshots['base'][p]!=snapshots['head'][p]]
 assert changed==['contract.json']
 a=snapshots['base']['contract.json'];b=snapshots['head']['contract.json'];assert a[0]==b[0]=='100644'
 patch='diff --git a/contract.json b/contract.json\nindex '+a[1][:7]+'..'+b[1][:7]+' 100644\n'
 patch+=''.join(difflib.unified_diff(a[2].decode().splitlines(True),b[2].decode().splitlines(True),fromfile='a/contract.json',tofile='b/contract.json'))
 assert patch.encode()==rd(s/'git-diff.patch')
 staging=js(s/'staging-command-log.json');assert all(e['returncode']==0 and e['stderr']=='' for e in staging)
 assert staging[-2]['stdout']==rd(s/'git-revisions.txt').decode() and staging[-1]['stdout']==patch
 print('Actual recorded diff independently reconstructed from archived Git blobs; all',len(objects),'Git object IDs valid; staging log agrees')
print('\nALL INVENTORY, FIXTURE, ARCHIVE, INSTRUCTION, MANIFEST AND GIT CHECKS PASSED')
